typedef unsigned int u_int;

#define D1_CHCR ((volatile u_int *)0x10009000)
#define D2_CHCR ((volatile u_int *)0x1000A000)
#define VIF1_FBRST ((volatile u_int *)0x10003C10)
#define GIF_CTRL ((volatile u_int *)0x10003000)
#define GIF_STAT ((volatile u_int *)0x10003020)

extern bool nglStopOnDmaTimeout;
extern bool nglCompleteFrame;
extern const char ngl_gif_dma_timeout[];

extern "C" int scePcStart(int, int, int);
void nglWarning(const char *, ...);

__asm__(".equ nglStopOnDmaTimeout, 0x004AB814");
__asm__(".equ nglCompleteFrame, 0x004AB818");
__asm__(".equ ngl_gif_dma_timeout, 0x0050D530");
__asm__(".equ scePcStart, 0x003C5DD0");
__asm__(".equ nglWarning__FPCce, 0x003AC088");

inline long volatile nglGetCPUCycle()
{
  register unsigned long result;
  __asm__ volatile ("mfc0 %0,$9" : "=r" (result));
  return result;
}

const u_int nglGifTimeOut = (u_int)(294912.0f * 100.0f);

void nglGifSafeWait()
{
  register u_int Start = nglGetCPUCycle();

  while ( (*D2_CHCR & 0x0100) || (*GIF_STAT & 0x0c00) )
  {
    u_int Time = nglGetCPUCycle();
    if ( Time - Start >= nglGifTimeOut )
    {
      nglCompleteFrame = !nglStopOnDmaTimeout;
      while (!nglCompleteFrame)
      {
        scePcStart( 0, 0, 0 );
      }
      nglWarning( ngl_gif_dma_timeout );
      *D1_CHCR = 1 | (1<<2) | (0<<4) | (0<<6) | (0<<7) | (0<<8);
      *D2_CHCR = 1 | (1<<2) | (0<<4) | (0<<6) | (0<<7) | (0<<8);
      *VIF1_FBRST = 1 | (1<<3);
      *GIF_CTRL = 1;
      break;
    }
  }
}
